import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import { createRequire } from "node:module";
import test from "node:test";

const require = createRequire(import.meta.url);
const { addFirebaseConfigureToSwiftAppDelegate } = require("./withFirebaseAppDelegateConfigure.js");

// AppDelegate.swift as generated by `expo prebuild` on Expo SDK 58, after
// @react-native-firebase/app 26.4.0 added its import but skipped
// FirebaseApp.configure() ("Unable to determine correct Firebase insertion point").
const SDK58_APP_DELEGATE = `internal import Expo
import FirebaseCore
import React
import ReactAppDependencyProvider

@main
class AppDelegate: ExpoAppDelegate, ExpoReactNativeFactoryProvider {
  var window: UIWindow?

  var reactNativeDelegate: ExpoReactNativeFactoryDelegate?
  var reactNativeFactory: RCTReactNativeFactory?

  public override func application(
    _ application: UIApplication,
    didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey: Any]? = nil
  ) -> Bool {
    let delegate = ReactNativeDelegate()
    let factory = ExpoReactNativeFactory(delegate: delegate)
    delegate.dependencyProvider = RCTAppDependencyProvider()

    reactNativeDelegate = delegate
    reactNativeFactory = factory

    return super.application(application, didFinishLaunchingWithOptions: launchOptions)
  }
}
`;

test("SDK 58 AppDelegate gets FirebaseApp.configure() inside didFinishLaunching, before super", () => {
  const out = addFirebaseConfigureToSwiftAppDelegate(SDK58_APP_DELEGATE);
  const configure = out.indexOf("    FirebaseApp.configure()\n");
  const superCall = out.indexOf("return super.application(application, didFinishLaunchingWithOptions: launchOptions)");
  const didFinish = out.indexOf("didFinishLaunchingWithOptions launchOptions:");
  assert.ok(configure > didFinish, "configure() must be inside didFinishLaunchingWithOptions");
  assert.ok(configure < superCall, "configure() must run before super.application(...)");
  assert.equal(out.match(/FirebaseApp\.configure\(\)/g).length, 1);
  assert.equal(out.match(/^import FirebaseCore$/gm).length, 1);
});

test("idempotent: re-running prebuild or an upstream fix never adds a second configure()", () => {
  const once = addFirebaseConfigureToSwiftAppDelegate(SDK58_APP_DELEGATE);
  assert.equal(addFirebaseConfigureToSwiftAppDelegate(once), once);
});

test("adds the FirebaseCore import when it is missing", () => {
  const out = addFirebaseConfigureToSwiftAppDelegate(SDK58_APP_DELEGATE.replace("import FirebaseCore\n", ""));
  assert.match(out, /^import FirebaseCore\ninternal import Expo$/m);
  assert.match(out, /FirebaseApp\.configure\(\)/);
});

test("fails prebuild loudly (not a warning) when the anchor disappears", () => {
  const changed = SDK58_APP_DELEGATE.replace(/return super\.application\([^)]*\)/, "return true");
  assert.throws(() => addFirebaseConfigureToSwiftAppDelegate(changed), /withFirebaseAppDelegateConfigure/);
});

test("the plugin is registered after the React Native Firebase plugins in app.json", async () => {
  const { expo } = JSON.parse(await readFile(new URL("../app.json", import.meta.url), "utf8"));
  const names = expo.plugins.map((plugin) => (Array.isArray(plugin) ? plugin[0] : plugin));
  const ours = names.indexOf("./plugins/withFirebaseAppDelegateConfigure.js");
  assert.ok(ours > names.indexOf("@react-native-firebase/app"));
  assert.ok(ours > names.indexOf("@react-native-firebase/messaging"));
  assert.equal(expo.ios.googleServicesFile, "./GoogleService-Info.plist");
});
